public interface ISingleFlight
{
    Task<T> RunAsync<T>(string key, Func<CancellationToken, Task<T>> factory, CancellationToken ct);
}

public sealed class SingleFlight : ISingleFlight
{
    private readonly object _sync = new();
    private readonly Dictionary<string, object> _inFlight = new();

    public async Task<T> RunAsync<T>(string key, Func<CancellationToken, Task<T>> factory, CancellationToken ct)
    {
        Task<T> shared;
        lock (_sync)
        {
            if (_inFlight.TryGetValue(key, out var existing))
            {
                shared = (Task<T>)existing;
            }
            else
            {
                var tcs = new TaskCompletionSource<T>(TaskCreationOptions.RunContinuationsAsynchronously);
                shared = tcs.Task;
                _inFlight[key] = shared;
                _ = CompleteFlightAsync(key, factory, tcs);
            }
        }
        return await shared.WaitAsync(ct).ConfigureAwait(false);
    }

    private async Task CompleteFlightAsync<T>(
        string key,
        Func<CancellationToken, Task<T>> factory,
        TaskCompletionSource<T> tcs)
    {
        try
        {
            var result = await factory(CancellationToken.None).ConfigureAwait(false);
            tcs.TrySetResult(result);
        }
        catch (Exception ex)
        {
            tcs.TrySetException(ex);
        }
        finally
        {
            lock (_sync)
            {
                if (_inFlight.TryGetValue(key, out var current) && ReferenceEquals(current, tcs.Task))
                {
                    _inFlight.Remove(key);
                }
            }
        }
    }
}
